+    cumulative_logprob: f32,
+    eos_token_id: Option<u32>,
+    length_penalty: f32,
+) -> f32 {
+    let mut seq_len = tokens.len();
+    if let Some(eos) = eos_token_id {
+        if tokens.last() == Some(&eos) {
